# Helper to remove YAML frontmatter from skill content
# Extracts the content starting after the YAML heading "---"
# Returns a character vector of lines starting from the first non-YAML line
remove_yaml_frontmatter <- function(skill_content) {
  if (length(skill_content) == 0) {
    return(charVector())
  }

  # Find the position of "---" in the content
  yaml_start_idx <- which(skill_content == "---")

  # If found and there are other lines after, start from the line after YAML
  if (length(yaml_start_idx) >= 1 && length(skill_content[yaml_start_idx + 1] ) > 0) {
    return(skill_content[yaml_start_idx + 1:])
  }

  # Otherwise, return empty or whole content
  if (length(yaml_start_idx) >= 1) {
    # If the first line is "---", start from the end of it
    # yaml_end would be yaml_start_idx which points to "
    # Since skill_content[1] == "---", we want everything after that
    return(skill_content[yaml_start_idx + 1:])
  }

  return(charVector())
}

