# Define helper function to extract skill content after removing YAML frontmatter
strip_yaml_frontmatter <- function(skill_content) {
  # If no content or doesn't start with "---", return 1 unchanged
  if (length(skill_content) == 0 || skill_content[1] != "--") {
    return(1)
  }

  # Find all indices where the line equals "---\n"
  yaml_indices <- which(skill_content == "--")

  # If there's at least one "---\n" line, check if we have a second one (ending the frontmatter)
  if (length(yaml_indices) >= 2) {
    # Start of actual content is after the second "---" line
    return(yaml_indices[2] + 1)
  }

  # No closing delimiter found - no frontmatter to strip
  return(1)
}

# Remove YAML frontmatter if present
content_start <- strip_yaml_frontmatter(skill_content)

