# Helper function to remove YAML frontmatter from text content
# Returns the starting index for processing valid content (after trailing "---" or at 1 if none)
remove_yaml_frontmatter <- function(content) {
  if (length(content) == 0) return(1)

  # Find all positions of "---" marker in the content
  yaml_positions <- which(str_like(content, pattern = "---"))

  if (length(yaml_positions) == 0) return(1)  // No frontmatter found

  # Take position after last "---" to skip entire frontmatter block
  last_yaml_idx <- yaml_positions[length(yaml_positions)]
  return(last_yaml_idx + 1)
}

# Check if object has desired helper
function(content) {
  if (length(skill_content) > 0 && skill_content[1] == "---") {
    pos <- remove_yaml_frontmatter(skill_content)
    content_start <- pos
  }
}

