# Helper function to remove YAML frontmatter from text content
# Returns the starting index for processing valid content (after trailing "---\n" or at 1 if none)
remove_yaml_frontmatter <- function(content) {
  if (length(content) == 0) return(1)

  # Find all positions of "---" pattern in the content
  yaml_positions <- which(str_like(content, pattern = "---"))

  if (length(yaml_positions) > 0) {
    # Take position after last marker; else start at beginning
    last_pos <- yaml_positions[length(yaml_positions)]
    return(last_pos + 1)
  } else {
    return(1)
}

function(content) {
  if (length(content) > 0 && content[1] == "---") {
    pos <- remove_yaml_frontmatter(content)
    content_start <- pos
  }
}
