# Helper functions for skill content processing

# Remove YAML frontmatter if present
remove_yaml_frontmatter <- function(skill_content) {
  # content_start tracks where the actual skill text begins
  content_start <- 1

  # If there's content and it starts with "---", process the frontmatter
  if (length(skill_content) > 0 && skill_content[1] == "---") {
    yaml_end <- which(skill_content == "---")
    if (length(yaml_end) >= 2) {
      # Set content_start to after the YAML frontmatter
      content_start <- yaml_end[2] + 1
    }
  }

  return(content_start)
}

