254: # When a user interrupts a streaming response, ellmer's Chat is left in an
255: # inconsistent state. Normally, ellmer only adds turns to the Chat history after
256: # a stream completes successfully. When we interrupt mid-stream,
257: # we need to ensure that user/assistant turns alternate back-and-forth, and that
258: # all tool requests have matching tool results.
259: #
260: # For the purposes of this app, interrupts either occur 1) during the tool
261: # calling loop or 2) not.
262: # 1) When during the tool calling loop, just confirm that tool calling loops
263: # appear complete by patching requests that don't have matching results with
264: # a text content.
265: # 2) When not during tool calling, process the streamed text content and
266: # let that form the assistant turn.
267: patch_interrupted_chat <- function(
268:   client,
269:   streamed_content = NULL,
270:   user_input = NULL
271: ) {
272:   # saveRDS(
273:   #   list(client = client, streamed_content = streamed_content, user_input = user_input),
274:   #   "/Users/simoncouch/.config/side/before_patching.rds"
275:   # )
276:   request_ids <- character()
277:   for (turn in client$get_turns()) {
278:     .res <- lapply(turn@contents, function(c) {
279:       if (S7::S7_inherits(c, ellmer::ContentToolRequest)) {
280:         request_ids <<- c(request_ids, c@id)
281:       }
282:     })
283:   }
284: 
285:   result_ids <- character()
286:   for (turn in client$get_turns()) {
287:     .res <- lapply(turn@contents, function(c) {
288:       if (S7::S7_inherits(c, ellmer::ContentToolResult)) {
289:         result_ids <<- c(result_ids, c@request@id)
290:       }
291:     })
292:   }
293: 
294:   requests_without_matches <- request_ids[!request_ids %in% result_ids]
295: 
296:   old_turns <- client$get_turns()
297:   new_turns <- list()
298:   for (turn in old_turns) {
299:     turn@contents <- lapply(turn@contents, function(c) {
300:       if (
301:         S7::S7_inherits(c, ellmer::ContentToolRequest) &&
302:           c@id %in% requests_without_matches
303:       ) {
304:         return(ellmer::ContentText(
305:           paste0("_Tool call to `", c@name, "` interrupted._")
306:         ))
307:       }
308: 
309:       c
310:     })
311: 
312:     new_turns <- c(new_turns, turn)
313:   }
314: 
315:   # If there are requests without matches, the interruption happended during
316:   # the tool calling loop. In that case, just patch the tool call turns and
317:   # don't worry about updating from other streamed content--ellmer already
318:   # had a chance to form complete turns up to the penultimate one.
319:   if (length(requests_without_matches) > 0) {
320:     client$set_turns(new_turns)
321:     return(client)
322:   }
323: 
324:   if (!is.null(streamed_content)) {
325:     text_content <- vapply(
326:       streamed_content,
327:       function(c) S7::S7_inherits(c, ellmer::ContentText),
328:       logical(1)
329:     )
330:     text_content <- paste0(
331:       vapply(streamed_content[text_content], function(c) c@text, character(1)),
332:       collapse = ""
333:     )
334:     text_content <- paste0(text_content, "...\n\n_Streaming interrupted._")
335: 
336:     if (length(new_turns) == 0) {
337:       last_turn_is_assistant <- TRUE
338:     } else {
339:       last_turn_is_assistant <- new_turns[[length(new_turns)]]@role ==
340:         "assistant"
341:     }
342: 
343:     if (last_turn_is_assistant) {
344:       new_turns <- c(
345:         new_turns,
346:         list(
347:           ellmer::Turn("user", list(ellmer::ContentText(user_input))),
348:           ellmer::Turn("assistant", list(ellmer::ContentText(text_content)))
349:         )
350:       )
351:     } else {
352:       # The most recent turn is a user turn, so update its contents with
353:       # the new user input
354:       last_user_turn <- new_turns[[length(new_turns)]]
355:       last_user_turn@contents <- c(
356:         last_user_turn@contents,
357:         ellmer::ContentText(user_input)
358:       )
359:       new_turns[[length(new_turns)]] <- last_user_turn
360: 
361:       new_turns <- c(
362:         new_turns,
363:         list(ellmer::Turn("assistant", list(ellmer::ContentText(text_content))))
364:       )
365:     }
366:   }
367: 
368:   client$set_turns(new_turns)
369:   client
370: }
