fetch_skill_impl <- function(skill_name, `_intent` = NULL) {
  skill_path <- find_skill(skill_name)

  if (is.null(skill_path)) {
    available <- list_available_skills()
    skill_names <- vapply(available, function(x) x$name, character(1))
    cli::cli_abort(
      c(
        "Skill {.val {skill_name}} not found.",
        "i" = "Available skills: {.val {skill_names}}"
      ),
      call = rlang::caller_env()
    )
  }

  skill_content <- readLines(skill_path, warn = FALSE)

  # Remove YAML frontmatter if present
  content_result <- remove_yaml_frontmatter(skill_content)

  # Continue with the remaining content (or original if no frontmatter)
  skill_text <- paste(
    skill_content[content_result$content_start:length(skill_content)],
    collapse = "\n"
  )

  ellmer::ContentToolResult(
    value = skill_text,
    extra = list(
      display = list(
        markdown = skill_text,
        title = htmltools::HTML(sprintf(
          "Skill: <code>%s</code>",
          skill_name
        )),
        icon = tool_icon("globe-book"),
        open = TRUE
      )
    )
  )
}

# Helper function to remove YAML frontmatter from skill content
# Returns a list with content_start (index where text begins) and end_pos (length of remaining content)
remove_yaml_frontmatter <- function(skill_content) {
  # If no content or doesn't start with "---", treat as no YAML
  if (length(skill_content) == 0 || skill_content[1] != "---") {
    return(list(content_start = 1, end_pos = -1))
  }

  # Find the first occurrence of "---"
  yaml_end <- which(skill_content == "---")

  # If there's at least one line after the frontmatter marker (skip the "---" line and field name)
  if (length(yaml_end) >= 2) {
    content_start <- yaml_end[2] + 1
    return(list(content_start = content_start, end_pos = length(skill_content)))
  }

  # No trailing YAML fields - entire content is non-YAML
  return(list(content_start = 1, end_pos = length(skill_content)))
}

