  skill_dirs <- get_skill_directories()

  for (dir in skill_dirs) {
    skill_path <- file.path(dir, paste0(skill_name, ".md"))
    if (file.exists(skill_path)) {
      return(skill_path)
    }
  }

  NULL
}

